--
-- Table structure for table `obj_character`
--

DROP TABLE IF EXISTS `obj_character`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `obj_character` (
  `UID` bigint unsigned NOT NULL,
  `char_firstname` varchar(15) NOT NULL,
  `char_lastname` varchar(50) NOT NULL DEFAULT '',
  `char_isActive` tinyint(1) NOT NULL DEFAULT '1',
  `char_raceID` int unsigned NOT NULL,
  `char_baseClassID` int unsigned NOT NULL,
  `char_promotionClassID` int DEFAULT NULL,
  `char_strMod` smallint NOT NULL DEFAULT '0',
  `char_dexMod` smallint NOT NULL DEFAULT '0',
  `char_conMod` smallint NOT NULL DEFAULT '0',
  `char_intMod` smallint NOT NULL DEFAULT '0',
  `char_spiMod` smallint NOT NULL DEFAULT '0',
  `char_experience` int unsigned NOT NULL DEFAULT '0',
  `char_skinColor` tinyint unsigned NOT NULL,
  `char_hairColor` tinyint unsigned NOT NULL,
  `char_hairStyle` tinyint NOT NULL,
  `char_beardColor` tinyint unsigned NOT NULL,
  `char_beardStyle` tinyint NOT NULL,
  `char_bindBuilding` bigint NOT NULL,
  `guildUID` bigint unsigned DEFAULT NULL,
  `guild_isInnerCouncil` tinyint unsigned NOT NULL DEFAULT '0',
  `guild_isRecruiter` tinyint unsigned NOT NULL DEFAULT '0',
  `guild_isTaxCollector` tinyint unsigned NOT NULL DEFAULT '0',
  `guild_isFullMember` tinyint unsigned NOT NULL DEFAULT '0',
  `guild_title` tinyint unsigned NOT NULL DEFAULT '0',
  `anniversery` tinyint NOT NULL DEFAULT '0',
  `hash` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`UID`),
