--
-- Table structure for table `obj_npc`
--

DROP TABLE IF EXISTS `obj_npc`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `obj_npc` (
  `UID` bigint unsigned NOT NULL,
  `npc_name` varchar(60) NOT NULL DEFAULT '',
  `npc_contractID` int unsigned DEFAULT NULL,
  `npc_guildID` int unsigned DEFAULT NULL,
  `npc_spawnX` float NOT NULL DEFAULT '0',
  `npc_spawnY` float NOT NULL DEFAULT '0',
  `npc_spawnZ` float NOT NULL DEFAULT '0',
  `npc_level` smallint unsigned NOT NULL DEFAULT '0',
  `npc_buyPercent` float unsigned NOT NULL DEFAULT '1',
  `npc_sellPercent` float unsigned NOT NULL DEFAULT '0.1',
  `npc_buildingID` int NOT NULL DEFAULT '0',
  `npc_pTable` int NOT NULL DEFAULT '0',
  `npc_sTable` int NOT NULL DEFAULT '0',
  `npc_rotation` float NOT NULL DEFAULT '0',
  `upgradeDate` datetime DEFAULT NULL,
  `npc_buildingFloor` int DEFAULT '-1',
  `npc_buildingLevel` int DEFAULT '-1',
  `npc_raceID` int DEFAULT '0',
  `equipmentSet` int NOT NULL DEFAULT '0',
  `runeSet` int NOT NULL DEFAULT '0',
  `rotation` float(255,4) DEFAULT '0.0000',
  PRIMARY KEY (`UID`),
  CONSTRAINT `ref_npc` FOREIGN KEY (`UID`) REFERENCES `object` (`UID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=COMPACT;
/*!40101 SET character_set_client = @saved_cs_client */;

