CREATE TABLE `static_itembase` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(60) DEFAULT NULL,
  `type` enum('DECORATION','WEAPON','ARMOR','HAIR','GOLD','RUNE','SCROLL','BOOK','COMMANDROD','POTION','KEY','GUILDCHARTER','JEWELRY','WINE','ALEJUG','DEED','CONTRACT','PET','FURNITURE','BEDROLL','FARMABLE','WATERBUCKET','GIFT','OFFERING','RESOURCE','TEARS','REALMCHARTER') NOT NULL DEFAULT 'DECORATION',
  `durability` float unsigned NOT NULL DEFAULT '1',
  `equipflag` int unsigned NOT NULL DEFAULT '0',
  `restrictFlag` int unsigned NOT NULL DEFAULT '0',
  `value` int unsigned NOT NULL DEFAULT '0',
  `weight` smallint unsigned NOT NULL DEFAULT '0',
  `color` tinyint unsigned NOT NULL DEFAULT '0',
  `skillRequired` varchar(60) NOT NULL DEFAULT '',
  `percentRequired` smallint unsigned NOT NULL DEFAULT '0',
  `mastery` varchar(60) DEFAULT NULL,
  `slashResist` float unsigned NOT NULL DEFAULT '0',
  `crushResist` float unsigned NOT NULL DEFAULT '0',
  `pierceResist` float unsigned NOT NULL DEFAULT '0',
  `blockMod` float unsigned NOT NULL DEFAULT '0',
  `defense` smallint unsigned NOT NULL DEFAULT '0',
  `dexPenalty` float unsigned NOT NULL DEFAULT '0',
  `damageType` varchar(60) DEFAULT NULL,
  `speed` float unsigned NOT NULL DEFAULT '0',
  `range` float unsigned NOT NULL DEFAULT '0',
  `minDamage` smallint unsigned NOT NULL DEFAULT '0',
  `maxDamage` smallint unsigned NOT NULL DEFAULT '0',
  `twoHanded` tinyint unsigned NOT NULL DEFAULT '0',
  `isStrBased` tinyint unsigned NOT NULL DEFAULT '0',
  `parryBonus` float unsigned NOT NULL DEFAULT '0',
  `numCharges` smallint unsigned NOT NULL DEFAULT '0',
  `useID` int NOT NULL DEFAULT '0',
  `useAmount` tinyint NOT NULL DEFAULT '0',
  `vendorType` int NOT NULL DEFAULT '0',
  `modTable` int NOT NULL DEFAULT '0',
  `itemHashID` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=7000514 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=COMPACT;
