  `equipsetID` int NOT NULL DEFAULT '0',
  `inventorySet` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`ID`),
  KEY `fk_contracts_mobbase` (`mobbaseID`)
) ENGINE=InnoDB AUTO_INCREMENT=1502027 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=COMPACT;
