CREATE PROCEDURE `account_transfers_wipe`()
MAIN: BEGIN
 
	DECLARE ID INT UNSIGNED;
	DECLARE done INT DEFAULT 0;

	DECLARE UIDC BIGINT UNSIGNED;
	DECLARE UID BIGINT UNSIGNED;
  DECLARE in_discordAccount VARCHAR(60);
	DECLARE in_uname VARCHAR(60);
	DECLARE in_passwd CHAR(60);
  DECLARE in_regDate DATETIME;
  DECLARE in_salt CHAR(30);
  DECLARE in_suspend TINYINT UNSIGNED;
  DECLARE in_discordAdmin TINYINT;
  DECLARE in_lastCharUID BIGINT;
  DECLARE in_lastUpdateRequest DATETIME;
  DECLARE in_status enum('BANNED','ACTIVE','ADMIN','TRASH');
		DECLARE ACCTUID BIGINT(10);

	DECLARE cur1 CURSOR FOR SELECT UID, discordAccount, acct_uname, acct_passwd, registrationDate, acct_salt, acct_suspend, discordAdmin, acct_lastCharUID, lastUpdateRequest, status 
FROM obj_account_wipe;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

	OPEN cur1;

	START TRANSACTION;

		read_loop: LOOP
			
			FETCH cur1 INTO ID, in_discordAccount, in_uname, in_passwd, in_regDate, in_salt, in_suspend, in_discordAdmin, in_lastCharUID, in_lastUpdateRequest, in_status;
			IF done THEN
				LEAVE read_loop;
			END IF;

		IF NOT EXISTS(SELECT NULL FROM `obj_account` WHERE `acct_uname`= in_uname) THEN
			INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'account', NULL);
			SET UID = LAST_INSERT_ID();
		
			INSERT HIGH_PRIORITY INTO `obj_account` (`UID`, `discordAccount`, `acct_uname`, `acct_passwd`, `registrationDate`, `acct_salt`, `acct_suspend`, `discordAdmin`, `acct_lastCharUID`, `lastUpdateRequest`, `status`) VALUES (UID, in_discordAccount, in_uname, in_passwd, in_regDate, in_salt, in_suspend, in_discordAdmin, NULL, in_lastUpdateRequest, in_status);
		END IF;
		END LOOP;

	COMMIT;	

	CLOSE cur1;

END MAIN ;;
DELIMITER ;
