CREATE PROCEDURE `baneHistory`()
BEGIN
DECLARE TOTAL INT(10);
DECLARE PENDING INT(10);
DECLARE DESTROY INT(10);
DECLARE CAPTURE INT(10);
DECLARE DEFEND INT(10);

SET TOTAL = (SELECT COUNT(*) FROM `warehouse_banehistory`);
SET PENDING = (SELECT COUNT(*) FROM `warehouse_banehistory` WHERE `resolution` = 'PENDING');
SET DESTROY = (SELECT COUNT(*) FROM `warehouse_banehistory` WHERE `resolution` = 'DESTROY');
SET CAPTURE = (SELECT COUNT(*) FROM `warehouse_banehistory` WHERE `resolution` = 'CAPTURE');
SET DEFEND = (SELECT COUNT(*) FROM `warehouse_banehistory` WHERE `resolution` = 'DEFEND');




SELECT TOTAL, PENDING, DESTROY, CAPTURE, DEFEND;
END ;;
DELIMITER ;
