CREATE PROCEDURE `building_CREATE`(IN `zoneUID` BIGINT UNSIGNED, IN `oUID` BIGINT UNSIGNED, IN `n` VARCHAR(255), IN `loadNum` INT, IN `locX` FLOAT, IN `locY` FLOAT, IN `locZ` FLOAT, IN `strX` FLOAT, IN `cHP` INT UNSIGNED, IN `invuln` VARCHAR(64), IN `strongbox` INT, IN `rank` INT, IN `upgradedate` DATETIME, IN `baseID` INT, IN `lac` FLOAT, IN `rotY` FLOAT)
MAIN: BEGIN 

		
		DECLARE UID BIGINT UNSIGNED;

		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;
		

		IF ISNULL(zoneUID) THEN
			SELECT -2 AS `errorno`, "Parent (zone) UID CANNOT be null" AS `errormsg`;
			LEAVE MAIN;
		ELSEIF NOT EXISTS(SELECT NULL FROM `obj_zone` WHERE `obj_zone`.`UID`= zoneUID) THEN
			SELECT -3 AS `errorno`, "Parent (zone) UID must exist" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		START TRANSACTION;

		INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'building', zoneUID);
		SET UID = LAST_INSERT_ID();

		INSERT HIGH_PRIORITY INTO obj_building (`UID`, `ownerUUID`, `name`, `meshUUID`, `locationX`, `locationY`, `locationZ`, `scale`, `doorState`, `currentHP`, `protectionState`, `currentGold`, `rank`,`upgradeDate`, `blueprintUUID`,`w`, `rotY`)
						VALUES (UID, oUID, n, loadNum, locX, locY, locZ, strX, 0, cHP, invuln, strongbox, `rank`, upgradedate, baseID, lac, rotY);

		COMMIT;

		SELECT UID AS `UID`;

	END MAIN ;;
DELIMITER ;
