CREATE PROCEDURE `character_CREATE`(IN `acctUID` BIGINT UNSIGNED, IN `fname` VARCHAR(15), IN `lname` VARCHAR(15) CHARSET 'utf8', IN `rID` INT UNSIGNED, IN `bCID` INT UNSIGNED, IN `strM` SMALLINT, IN `dexM` SMALLINT, IN `conM` SMALLINT, IN `intM` SMALLINT, IN `spiM` SMALLINT, IN `exp` TINYINT UNSIGNED, IN `skinC` TINYINT UNSIGNED, IN `hairC` TINYINT UNSIGNED, IN `hairS` TINYINT, IN `beardC` TINYINT UNSIGNED, IN `beardS` TINYINT)
    MODIFIES SQL DATA
MAIN: BEGIN

		
		DECLARE UID BIGINT UNSIGNED;
		DECLARE UIDC BIGINT UNSIGNED;
		DECLARE UIDD BIGINT UNSIGNED;
		
		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, CONCAT ('UID: ', UID, ', char_firstname: ', fname, ', char_lastname: ', lname, ', char_raceID: ', rID, ', char_baseClassID: ', bCID, ', char_strMod: ', strM, ', char_dexMod: ', dexM, ', char_conMod: ', conM, ', char_intMod: ', intM, ', char_spiMod: ', spiM, ', char_experience: ', exp, ', char_skinColor: ', skinC, ', char_hairColor: ', hairC, ', char_hairStyle: ', hairS, ', char_beardColor: ', beardS, ', char_beardStyle: ', beardS, ', char_bindBuilding: ', '-1', ', acctUID: ', acctUID) as `errormsg`;
			
		END;
		
		IF ISNULL(acctUID) THEN
			SELECT -2 AS `errorno`, "Parent (account) UID CANNOT be null" AS `errormsg`;
			LEAVE MAIN;
		ELSEIF NOT EXISTS(SELECT NULL FROM `obj_account` WHERE `obj_account`.`UID`= acctUID) THEN
			SELECT -3 AS `errorno`, "Parent (account) UID must exist" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		START TRANSACTION;

		INSERT HIGH_PRIORITY INTO `object` VALUES (NULL, 'character', acctUID);
		SET UID = LAST_INSERT_ID();

		INSERT HIGH_PRIORITY INTO `obj_character` (`UID`, `char_firstname`, `char_lastname`, `char_raceID`, `char_baseClassID`, `char_strMod`, `char_dexMod`, `char_conMod`, `char_intMod`, `char_spiMod`, `char_experience`, `char_skinColor`, `char_hairColor`, `char_hairStyle`, `char_beardColor`, `char_beardStyle`, `char_bindBuilding`, `char_isActive`) VALUES (UID, fname, convert(lname using utf8), rID, bCID, strM, dexM, conM, intM, spiM, exp, skinC, hairC, hairS, beardC, beardS, -1, 1);

		COMMIT;

		SELECT UID AS `UID`;

	END MAIN ;;
DELIMITER ;
