CREATE PROCEDURE `container_CREATE`(IN `oUID` BIGINT UNSIGNED, IN `type` ENUM('bank','inventory','vault'))
MAIN: BEGIN

		
		DECLARE UID BIGINT UNSIGNED;

		
		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;
		
		

		IF ISNULL(oUID) THEN
			SELECT -2 AS `errorno`, "Parent (object) UID CANNOT be null" AS `errormsg`;
			LEAVE MAIN;
		ELSEIF NOT EXISTS(SELECT NULL FROM `object` WHERE `object`.`UID`= oUID AND `object`.`type` IN ('account', 'character') ) THEN
			SELECT -3 AS `errorno`, "Parent (object) UID must exist, and must be an account or character" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		

		START TRANSACTION;

		INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'container', oUID);
		SET UID = LAST_INSERT_ID();

		INSERT HIGH_PRIORITY INTO obj_container (`UID`, `container_type`)
						VALUES (UID, type);

		COMMIT;

		

		SELECT UID AS `UID`;

	END MAIN ;;
DELIMITER ;
