CREATE PROCEDURE `discordAccountCharacters`(IN `uname` VARCHAR(60))
MAIN: BEGIN
  DECLARE CHAR_COUNT int;
  SET CHAR_COUNT = (select COUNT(acct_uname) from char_perAccount Where acct_uname like CONCAT(uname,'%'));

  If CHAR_COUNT > 0 THEN
    	SELECT acct_uname, CharacterName, BaseClass, PromotionClass, char_level
      FROM char_perAccount
      Where acct_uname like CONCAT(uname,'%');
  Else Select acct_uname as 'Account Name','No Characters On This Account' as 'Characters' from obj_account where acct_uname like CONCAT(uname,'%');
  End If;
	END MAIN ;;
DELIMITER ;
