CREATE PROCEDURE `discordAccountExistsCheck`(IN `email` VARCHAR(60),IN `uname` VARCHAR(60),IN `passwd` CHAR(60))
    MODIFIES SQL DATA
MAIN: BEGIN
DECLARE ACCT_COUNT int;
SET ACCT_COUNT = (select COUNT(acct_uname) from obj_account Where acct_uname like CONCAT('%',uname,'%'));

If ACCT_COUNT > 0 THEN
  Select 'Username already in use, please choose a different name' as 'Failed';
  
Else
  CALL discordAccountRegister(email,uname,passwd);
  End IF;
	END MAIN ;;
