CREATE PROCEDURE `discordAccountRegister`(IN `discordAccount` VARCHAR(60), IN `discordName` VARCHAR(60), IN `passwd` CHAR(60))
    MODIFIES SQL DATA
MAIN: BEGIN

	CALL discordAccountCreate(discordAccount, CONCAT(discordName, "#1"), passwd);
	CALL discordAccountCreate(discordAccount, CONCAT(discordName, "#2"), passwd);
	CALL discordAccountCreate(discordAccount, CONCAT(discordName, "#3"), passwd);
	CALL discordAccountCreate(discordAccount, CONCAT(discordName, "#4"), passwd);

	END MAIN ;;
