CREATE PROCEDURE `discordUpdatePassword`(IN `uname` VARCHAR(60), IN `passwd` VARCHAR(60))
    MODIFIES SQL DATA
MAIN: BEGIN

		DECLARE SALTSTRING VARCHAR(60);
		DECLARE NEWPASS VARCHAR(60);

		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 

		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;

		START TRANSACTION;

		SET SALTSTRING = (SELECT SUBSTRING(MD5(RAND()) FROM 1 FOR 8) AS SALT);
		SET NEWPASS = (MD5(CONCAT(MD5(passwd), SALTSTRING)));

		

		UPDATE `obj_account` SET `acct_passwd` = NEWPASS, `acct_salt` = SALTSTRING, `lastUpdateRequest` = CURRENT_TIMESTAMP() WHERE `discordAccount` = uname;

		

		INSERT IGNORE INTO login_cachelist (`UID`) (SELECT `UID` from `obj_account` where `discordAccount` = uname);
		
		
		SELECT 1;

		COMMIT;

	END MAIN ;;
DELIMITER ;
