CREATE PROCEDURE `Find_UID`(IN `uname` VARCHAR(60))
BEGIN
	
		DECLARE CHARUID BIGINT(10);
		DECLARE ACCTUID BIGINT(10);

		SET CHARUID = (SELECT `UID` FROM `obj_character` WHERE `char_firstname` = uname);
		SET ACCTUID = (SELECT `parent` FROM `object` WHERE `UID` = CHARUID);

		select * FROM `obj_account` where `UID` = ACCTUID;
		SELECT * FROM `dyn_ip_account` WHERE `AccountID` = ACCTUID ORDER BY LastUsedDate DESC;
		
END ;;
DELIMITER ;
