CREATE PROCEDURE `forum_link_pass`(IN `uname` VARCHAR(60), IN `passwd` VARCHAR(60))
    MODIFIES SQL DATA
MAIN: BEGIN

		DECLARE SALTSTRING VARCHAR(60);
		DECLARE NEWPASS VARCHAR(60);
		DECLARE ACCTUID BIGINT(10);

		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 

		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;
			
		
		

		START TRANSACTION;
	  
		SET ACCTUID = (SELECT `UID` FROM `obj_account` WHERE `acct_uname`= uname);

		IF ACCTUID IS NULL THEN
		LEAVE MAIN;
		END IF;

		SET SALTSTRING = (SELECT SUBSTRING(MD5(RAND()) FROM 1 FOR 8) AS SALT);
		SET NEWPASS = (MD5(CONCAT(MD5(passwd), SALTSTRING)));

		

		UPDATE `obj_account` SET `acct_passwd` = NEWPASS, `acct_salt` = SALTSTRING WHERE `acct_uname`= uname  and acct_accessLevel not in(3) LIMIT 1;

		

		INSERT IGNORE INTO login_cachelist (`UID`) VALUES(ACCTUID);

		
		SELECT 1;

		COMMIT;

	END MAIN ;;
DELIMITER ;
