CREATE PROCEDURE `GET_POPULATION_STRING`()
BEGIN
DECLARE POPSTRING varchar(50);
DECLARE CHARCOUNT INT(10);
DECLARE GUILDCOUNT INT(10);
DECLARE CITYCOUNT INT(10);
DECLARE REALMCOUNT INT(10);

SET CHARCOUNT = (SELECT COUNT(*) FROM `obj_character`);
SET GUILDCOUNT = (SELECT COUNT(*) FROM `obj_guild`);
SET CITYCOUNT = (SELECT COUNT(*) FROM `obj_city` WHERE isNpc = 0);
SET REALMCOUNT = (SELECT COUNT(*) FROM `obj_realm` WHERE rulingCityUID != 0);

SET POPSTRING = (SELECT CONCAT("Chars:", CHARCOUNT, " Guilds:", GUILDCOUNT, " Cities:", CITYCOUNT, " Rulers:", REALMCOUNT));
SELECT POPSTRING;
END ;;
DELIMITER ;
