CREATE PROCEDURE `guild_CREATE`(IN `wsUID` BIGINT UNSIGNED, IN `lUID` BIGINT UNSIGNED, IN `n` VARCHAR(60), IN `bgC1` SMALLINT UNSIGNED, IN `bgC2` SMALLINT UNSIGNED, IN `sC` SMALLINT UNSIGNED, IN `bgD` SMALLINT UNSIGNED, IN `sym` SMALLINT UNSIGNED, IN `chart` SMALLINT UNSIGNED, IN `LType` VARCHAR(40), IN `motto` VARCHAR(120))
MAIN: BEGIN

		
		DECLARE UID BIGINT UNSIGNED;
		
		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
 BEGIN
    GET DIAGNOSTICS CONDITION 1 @ERRNO = MYSQL_ERRNO, @MESSAGE_TEXT = MESSAGE_TEXT;
		SELECT @ERRNO, @MESSAGE_TEXT;
    ROLLBACK; 
 END;
		
		IF ISNULL(lUID) THEN
			SELECT -2 AS `errorno`, "Leader (character) UID CANNOT be null" AS `errormsg`;
			LEAVE MAIN;
		ELSEIF NOT EXISTS(SELECT NULL FROM `obj_character` WHERE `obj_character`.`UID`= lUID) THEN
			SELECT -3 AS `errorno`, "Leader (character) UID must exist" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		IF ISNULL(wsUID) THEN
			SELECT -2 AS `errorno`, "Server UID CANNOT be null" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		START TRANSACTION;

		INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'guild', wsUID);
		SET UID = LAST_INSERT_ID();

		INSERT HIGH_PRIORITY INTO obj_guild (`UID`, `name`, `backgroundColor01`, `backgroundColor02`, `symbolColor`, `backgroundDesign`, `symbol`, `charter`, `leadershipType`, `leaderUID`, `motto`)
						VALUES (UID, n, bgC1, bgC2, sC, bgD, sym, chart, LType, lUID, motto);

		COMMIT;
		
		SELECT UID AS `UID`;

	END MAIN ;;
DELIMITER ;
