CREATE PROCEDURE `guild_GETSETPROP`(IN `uid` bigint unsigned, IN `in_name` varchar(255), IN `in_new_value` varchar(255), IN `in_old_value` varchar(255))
MAIN: BEGIN

	DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
	BEGIN 
		ROLLBACK; 
		SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
	END;

	SET @dyn_sql = CONCAT('UPDATE `obj_guild` SET ',in_name,' = ? WHERE `obj_guild`.`UID` = ? AND ',in_name,' = ? LIMIT 1;'), @new_value = in_new_value, @uid = uid, @old_value = in_old_value;
	PREPARE stmt1 FROM @dyn_sql;
	EXECUTE stmt1 USING @new_value, @uid, @old_value;

	SET @dyn_sql = CONCAT('SELECT `',in_name,'` INTO @result FROM `obj_guild` WHERE `obj_guild`.`UID` = ? LIMIT 1;');
	PREPARE stmt2 FROM @dyn_sql;
	EXECUTE stmt2 USING @uid;

	DEALLOCATE PREPARE stmt1;
	DEALLOCATE PREPARE stmt2;

	SELECT @result AS result;

END MAIN ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
