CREATE PROCEDURE `item_CREATE`(IN `pUID` BIGINT UNSIGNED, IN `ibaseType` INT UNSIGNED, IN `chargeR` SMALLINT UNSIGNED, IN `duraC` SMALLINT UNSIGNED, IN `duraM` SMALLINT UNSIGNED, IN `numOf` MEDIUMINT UNSIGNED, IN `cont` ENUM('bank','equip','inventory','vault', 'forge'), IN `eSlot` SMALLINT UNSIGNED, IN `flags` INT, IN `customName`  VARCHAR(100))
    MODIFIES SQL DATA
