CREATE PROCEDURE `item_TRADE`(IN `in_ItemsA` TEXT, IN `in_PlayerA_UID` BIGINT UNSIGNED, IN `in_ItemsB` TEXT, IN `in_PlayerB_UID` BIGINT UNSIGNED, IN `in_GoldA_Amount` INT, IN `in_GoldA_UID` BIGINT, IN `in_GoldB_Amount` INT, IN `in_GoldB_UID` BIGINT)
Main: BEGIN

		DECLARE UID BIGINT UNSIGNED;
		DECLARE cnt INT UNSIGNED DEFAULT 1;
		DECLARE totA INT UNSIGNED DEFAULT 0;
		DECLARE totB INT UNSIGNED DEFAULT 0;
		DECLARE in_parent BIGINT UNSIGNED;
		DECLARE in_container ENUM('bank','equip','inventory','vault','none');
		DECLARE in_curGoldA INT UNSIGNED DEFAULT 0;
		DECLARE in_curGoldB INT UNSIGNED DEFAULT 0;

		DECLARE cur1 CURSOR FOR SELECT `object`.`parent`, `obj_item`.`item_container` FROM `obj_item` LEFT JOIN `object` ON `obj_item`.`UID` = `object`.`UID` WHERE `object`.`UID` = UID FOR UPDATE;
		DECLARE cur2 CURSOR FOR SELECT `object`.`parent`, `obj_item`.`item_container`, `obj_item`.`item_numberOfItems` FROM `obj_item` LEFT JOIN `object` ON `obj_item`.`UID` = `object`.`UID` WHERE `object`.`UID` = UID FOR UPDATE;
		
		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;
		
		START TRANSACTION;

		
		IF NOT EXISTS(SELECT NULL FROM `obj_character` WHERE `obj_character`.`UID`= in_PlayerA_UID) OR NOT EXISTS(SELECT NULL FROM `obj_character` WHERE `obj_character`.`UID`= in_PlayerB_UID) THEN
			SELECT -5 AS `errorno`, "Player Not found." AS `errormsg`;
			ROLLBACK;
			LEAVE MAIN;
		END IF;

		
		SET totA = `function_stringCount`(in_ItemsA, ',');
		SET totB = `function_stringCount`(in_ItemsB, ',');

		
		IF (totA > 256 OR totB > 256) THEN
			SELECT -2 AS `errorno`, "Max 256 objects can be handled trading." AS `errormsg`;
			ROLLBACK;
			LEAVE MAIN;
		END IF;

		
		WHILE (cnt <= totA) DO
			SET UID = `function_strSplit`(in_ItemsA, ',', cnt);

			
			IF (`function_isNumeric`(UID) != 1 OR UID = 0) THEN
				SELECT -3 AS `errorno`, "Non-Numeric Number passed." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;

			open cur1;
			FETCH cur1 INTO in_parent, in_container;		
			close cur1;

			IF (in_parent != in_PlayerA_UID OR in_container != 'inventory') THEN
				SELECT -4 AS `errorno`, "Invalid parent or item not in inventory." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;

			SET cnt = cnt + 1;

		END WHILE;

		
		SET cnt = 1;
		WHILE (cnt <= totB) DO
			SET UID = `function_strSplit`(in_ItemsB, ',', cnt);

			
			IF (`function_isNumeric`(UID) != 1 OR UID = 0) THEN
				SELECT -3 AS `errorno`, "Non-Numeric Number passed." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;

			open cur1;
			FETCH cur1 INTO in_parent, in_container;		
			close cur1;

			IF (in_parent != in_PlayerB_UID OR in_container != 'inventory') THEN
				SELECT -4 AS `errorno`, "Invalid parent or item not in inventory." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;

			SET cnt = cnt + 1;

		END WHILE;

		
		IF (in_GoldA_UID > 0) THEN
			SET UID = in_GoldA_UID;

			open cur2;
			FETCH cur2 INTO in_parent, in_container, in_curGoldA;
			close cur2;	

			IF (in_parent != in_PlayerA_UID OR in_container != 'inventory') THEN
				SELECT -4 AS `errorno`, "Invalid parent or gold not in inventory." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;			

			IF (in_GoldA_Amount > in_curGoldA) THEN
				SELECT -6 AS `errorno`, "not enough gold in inventory to transfer." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;			
		ELSE
				SELECT -7 AS `errorno`, "Missing gold ID." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
		END IF;

		
		IF (in_GoldB_UID > 0) THEN
			SET UID = in_GoldB_UID;

			open cur2;
			FETCH cur2 INTO in_parent, in_container, in_curGoldB;
			close cur2;	

			IF (in_parent != in_PlayerB_UID OR in_container != 'inventory') THEN
				SELECT -4 AS `errorno`, "Invalid parent or gold not in inventory." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;			

			IF (in_GoldB_Amount > in_curGoldB) THEN
				SELECT -6 AS `errorno`, "not enough gold in inventory to transfer." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
			END IF;			
		ELSE
				SELECT -7 AS `errorno`, "Missing gold ID." AS `errormsg`;
				ROLLBACK;
				LEAVE MAIN;
		END IF;

		

		
		Set cnt = 1;
		WHILE (cnt <= totA) DO
			SET UID = `function_strSplit`(in_ItemsA, ',', cnt);

			SET @dyn_sql = CONCAT('UPDATE `object` SET `parent` = ? WHERE `UID` = ? AND `parent` = ? LIMIT 1;'), @parent = in_PlayerB_UID, @uid = uid, @curOwner = in_PlayerA_UID;
			PREPARE stmt1 FROM @dyn_sql;
			EXECUTE stmt1 USING @parent, @uid, @curOwner;

			SET cnt = cnt + 1;

		END WHILE;

		
		Set cnt = 1;
		WHILE (cnt <= totB) DO
			SET UID = `function_strSplit`(in_ItemsB, ',', cnt);

			SET @dyn_sql = CONCAT('UPDATE `object` SET `parent` = ? WHERE `UID` = ? AND `parent` = ? LIMIT 1;'), @parent = in_PlayerA_UID, @uid = uid, @curOwner = in_PlayerB_UID;
			PREPARE stmt1 FROM @dyn_sql;
			EXECUTE stmt1 USING @parent, @uid, @curOwner;

			SET cnt = cnt + 1;

		END WHILE;

		
		IF (in_GoldA_Amount > 0 OR in_GoldB_Amount > 0) THEN
			
			Set in_curGoldA = in_curGoldA - in_GoldA_Amount + in_GoldB_Amount;
			Set in_curGoldB = in_curGoldB + in_GoldA_Amount - in_GoldB_Amount;

			SET @dyn_sql = CONCAT('UPDATE `obj_item` SET `item_numberOfItems` = ? WHERE `UID` = ? LIMIT 1;'), @numGold = in_curGoldB, @uid = in_GoldB_UID;
			PREPARE stmt2 FROM @dyn_sql;
			EXECUTE stmt2 USING @numGold, @uid;			

			SET @dyn_sql = CONCAT('UPDATE `obj_item` SET `item_numberOfItems` = ? WHERE `UID` = ? LIMIT 1;'), @numGold = in_curGoldA, @uid = in_GoldA_UID;
			PREPARE stmt3 FROM @dyn_sql;
			EXECUTE stmt3 USING @numGold, @uid;			

		END IF;

		COMMIT;

		Select 1 AS 'result';	

END Main ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `item_TRANSFER_OWNER` */;
