CREATE PROCEDURE `item_TRANSFER_OWNER`(IN `UID` BIGINT, IN `newParent` BIGINT, IN `newContainer` ENUM('bank','equip','inventory','vault','forge','none'), IN `equipSlot` INT)
MAIN: BEGIN

	DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
	BEGIN 
		ROLLBACK; 
		SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
	END;

	START TRANSACTION;

	SET @dyn_sql = CONCAT('UPDATE `obj_item` INNER JOIN `object` ON `object`.`UID` = `obj_item`.`UID` SET `object`.`parent`=?, `obj_item`.`item_container`=?, `obj_item`.`item_equipSlot`=? WHERE `object`.`UID`=?'), @parent = newParent, @container = newContainer, @equipSlot = equipSlot, @uid = UID;
	PREPARE stmt1 FROM @dyn_sql;
	EXECUTE stmt1 USING @parent, @container, @equipSlot, @uid;
	DEALLOCATE PREPARE stmt1;
	COMMIT;

	SELECT '1' AS `result`;
	
END MAIN ;;
