CREATE PROCEDURE `item_TRANSFER_OWNER_WAREHOUSE`(IN `UID` BIGINT, IN `oldParent` BIGINT, IN `newParent` BIGINT, IN `oldContainer` ENUM('bank','equip','inventory','vault','warehouse','none'), IN `newContainer` ENUM('bank','equip','inventory','vault','warehouse','none'))
MAIN: BEGIN

	DECLARE in_parent BIGINT UNSIGNED;
	DECLARE in_container ENUM('bank','equip','inventory','vault', 'warehouse', 'none');
	

	DECLARE cur1 CURSOR FOR SELECT `object`.`parent`, `obj_item`.`item_container` FROM `obj_item` INNER JOIN `object` ON `obj_item`.`UID` = `object`.`UID` WHERE `object`.`UID` = UID;
	

	DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
	BEGIN 
		ROLLBACK; 
		SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
	END;

	OPEN cur1;
	FETCH cur1 INTO in_parent, in_container; 
	CLOSE cur1;

	
	IF (in_parent != oldParent) THEN
		SELECT -2 AS `errorno`, "Old Parent not correct" AS `errormsg`;
		LEAVE MAIN;
	END IF;

	
	IF (in_container != oldContainer) THEN
		SELECT -3 AS `errorno`, "Old Container no correct" AS `errormsg`;
		LEAVE MAIN;
	END IF;	

	
	SET @dyn_sql = CONCAT('UPDATE `obj_item` INNER JOIN `object` ON `object`.`UID` = `obj_item`.`UID` SET `object`.`parent`=?, `obj_item`.`item_container`=? WHERE `object`.`UID`=?'), @parent = newParent, @container = newContainer, @equipSlot = equipSlot, @uid = UID;
	PREPARE stmt1 FROM @dyn_sql;
	EXECUTE stmt1 USING @parent, @container, @uid;
	DEALLOCATE PREPARE stmt1;

	SELECT '1' AS `result`;

END MAIN ;;
DELIMITER ;
