CREATE PROCEDURE `mob_CREATE`(IN `zoneUID` BIGINT, IN `mobbaseID` INT, IN `guildID` BIGINT, IN `spawnX` FLOAT, IN `spawnY` FLOAT, IN `spawnZ` FLOAT, IN `spawnType` SMALLINT, IN `spawnRadius` FLOAT, IN `spawnTime` INT, IN `contractID` INT,  IN `buildingID` INT, IN `moblevel` INT, IN `mobname` VARCHAR(60))
MAIN: BEGIN

		
	DECLARE UID BIGINT UNSIGNED;

	DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
