CREATE PROCEDURE `object_GETSETPARENT`(IN `oUID` BIGINT UNSIGNED, IN `pUID` BIGINT UNSIGNED, IN `oldPUID` BIGINT UNSIGNED)
MAIN: BEGIN

		

		
		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;
		
		

		

		UPDATE `object` SET `object`.`parent` = pUID WHERE `object`.`UID` = oUID AND `object`.`parent` = oldPUID LIMIT 1;
		SELECT `object`.`parent` INTO @result FROM `object` WHERE `object`.`UID` = oUID LIMIT 1;

		

		SELECT @result AS `UID`;

	END MAIN ;;
DELIMITER ;
