CREATE PROCEDURE `PURGE_ORPHANS`()
BEGIN

DECLARE v_uid INT;
DECLARE done INT DEFAULT FALSE;
DECLARE cur1 CURSOR for SELECT `UID` from object WHERE type = 'item' and parent IS NULL;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

OPEN cur1;

loopy_doopy: LOOP

FETCH cur1 INTO v_uid;

if done THEN
 LEAVE loopy_doopy;
END IF;

START TRANSACTION;
delete from object where object.UID = v_uid;
COMMIT;

END LOOP loopy_doopy;

CLOSE cur1;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
