CREATE PROCEDURE `pvpHistory`(IN `CharUUID` varchar(20))
BEGIN
DECLARE TOTALDEATHS INT(10);
DECLARE KILLCOUNT INT(10);
DECLARE DEATHCOUNT INT(10);
DECLARE HOURLYKILLS INT(10);
DECLARE HOURLYDEATHS INT(10);
DECLARE DAILYKILLS INT(10);
DECLARE DAILYDEATHS INT(10);

SET TOTALDEATHS = (SELECT COUNT(*) FROM `warehouse_pvphistory`);
SET KILLCOUNT = (SELECT COUNT(*) FROM `warehouse_pvphistory` where `char_id` = `CharUUID`);
SET DEATHCOUNT = (SELECT COUNT(*) FROM `warehouse_pvphistory` where `victim_id` = `CharUUID`);

SET DAILYKILLS = (SELECT COUNT(*) FROM `warehouse_pvphistory` where datetime > DATE_SUB(NOW(), INTERVAL 1 DAY) AND `char_id` = `CharUUID`);
SET DAILYDEATHS = (SELECT COUNT(*) FROM `warehouse_pvphistory` where datetime > DATE_SUB(NOW(), INTERVAL 1 DAY) AND `victim_id` = `CharUUID`);

SET HOURLYKILLS = (SELECT COUNT(*) FROM `warehouse_pvphistory` where datetime > DATE_SUB(NOW(), INTERVAL 1 HOUR) AND `char_id` = `CharUUID`);
SET HOURLYDEATHS = (SELECT COUNT(*) FROM `warehouse_pvphistory` where datetime > DATE_SUB(NOW(), INTERVAL 1 HOUR) AND `victim_id` = `CharUUID`);

SELECT TOTALDEATHS, KILLCOUNT, DEATHCOUNT, HOURLYKILLS, HOURLYDEATHS, DAILYKILLS, DAILYDEATHS;
END ;;
DELIMITER ;
