CREATE PROCEDURE `shrine_CREATE`(
	IN `zoneUID` BIGINT UNSIGNED,
	IN `oUID` BIGINT UNSIGNED,
	IN `n` VARCHAR (255),
	IN `loadNum` INT,
	IN `locX` FLOAT,
	IN `locY` FLOAT,
	IN `locZ` FLOAT,
	IN `strX` FLOAT,
	IN `cHP` INT UNSIGNED,
	IN `invuln` VARCHAR (64),
	IN `strongbox` INT,
	IN `rank` TINYINT,
	IN `upgradedate` DATETIME,
	IN `baseID` INT,
	IN `lac` FLOAT,
	IN `rotY` FLOAT,
	IN `shrineType` VARCHAR (64)
)
MAIN :
BEGIN
	DECLARE
		UID BIGINT UNSIGNED;

DECLARE
	shrineUID BIGINT UNSIGNED;

DECLARE
	EXIT HANDLER FOR SQLEXCEPTION,
	SQLWARNING,
	NOT FOUND
BEGIN
	ROLLBACK;

SELECT
	- 1 AS `errorno`,
	"SQL Error: A rollback has occured." AS `errormsg`;


END;


IF ISNULL(zoneUID) THEN
	SELECT
		- 2 AS `errorno`,
		"Parent (zone) UID CANNOT be null" AS `errormsg`;

LEAVE MAIN;


ELSEIF NOT EXISTS (
	SELECT
		NULL
	FROM
		`obj_zone`
	WHERE
		`obj_zone`.`UID` = zoneUID
) THEN
	SELECT
		- 3 AS `errorno`,
		"Parent (zone) UID must exist" AS `errormsg`;

LEAVE MAIN;


END
IF;

START TRANSACTION;

INSERT HIGH_PRIORITY INTO object
VALUES
	(NULL, 'building', zoneUID);


SET UID = LAST_INSERT_ID();

INSERT HIGH_PRIORITY INTO obj_building (
	`UID`,
	`ownerUUID`,
	`name`,
	`meshUUID`,
	`locationX`,
	`locationY`,
	`locationZ`,
	`scale`,
	`doorState`,
	`currentHP`,
	`protectionState`,
	`currentGold`,
	`rank`,
	`upgradeDate`,
	`blueprintUUID`,
	`w`,
	`rotY`
)
VALUES
	(
		UID,
		oUID,
		n,
		loadNum,
		locX,
		locY,
		locZ,
		strX,
		0,
		cHP,
		invuln,
		strongbox,
		`rank`,
		upgradedate,
		baseID,
		lac,
		rotY
	);

INSERT HIGH_PRIORITY INTO object
VALUES
	(NULL, 'shrine', UID);


SET shrineUID = LAST_INSERT_ID();

INSERT HIGH_PRIORITY INTO obj_shrine (
	`UID`,
	`shrine_type`,
	`shrine_favors`
)
VALUES
	(shrineUID, shrineType, 0);


SELECT
	`obj_building`.*, `object`.`parent`,
	`object`.`type`
FROM
	`object`
LEFT JOIN `obj_building` ON `object`.`UID` = `obj_building`.`UID`
WHERE
	`object`.`UID` = UID;


SELECT
	`obj_shrine`.*, `object`.`parent`,
	`object`.`type`
FROM
	`object`
LEFT JOIN `obj_shrine` ON `object`.`UID` = `obj_shrine`.`UID`
WHERE
	`object`.`UID` = shrineUID;

COMMIT;


END MAIN ;;
DELIMITER ;
