CREATE PROCEDURE `singleAccountCreate`(IN `uname` VARCHAR(60), IN `passwd` CHAR(60))
    MODIFIES SQL DATA
MAIN: BEGIN

		DECLARE UID BIGINT UNSIGNED;
		DECLARE SALTSTRING VARCHAR(8);

		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;

		START TRANSACTION;
		
		INSERT HIGH_PRIORITY INTO `object` VALUES (NULL, 'account', NULL);
		SET UID = LAST_INSERT_ID();

		SET SALTSTRING = (SELECT SUBSTRING(MD5(RAND()) FROM 1 FOR 8) AS SALT);

		INSERT HIGH_PRIORITY INTO `obj_account` (`UID`, `acct_uname`, `acct_passwd`, `acct_salt`, `discordAccount`, `registrationDate`)
							VALUES (UID, uname,MD5(CONCAT(MD5(passwd), SALTSTRING)), SALTSTRING,  uuid(), CURRENT_TIMESTAMP());
		
		INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'container', UID);
		SET UID = LAST_INSERT_ID();

		INSERT HIGH_PRIORITY INTO obj_container (`UID`, `container_type`)
						VALUES (UID, 'vault');
		COMMIT;
		
		
		SELECT 1;

	END MAIN ;;
DELIMITER ;
