CREATE PROCEDURE `transfer_accounts`()
MAIN: BEGIN
 
	DECLARE ID INT UNSIGNED;
	DECLARE done INT DEFAULT 0;

	DECLARE UIDC BIGINT UNSIGNED;
	DECLARE UID BIGINT UNSIGNED;
	DECLARE in_uname VARCHAR(60);
	DECLARE in_passwd VARCHAR(60);
	DECLARE in_email VARCHAR(200);
	DECLARE in_accessLevel SMALLINT UNSIGNED;
	DECLARE in_lastCharUsedID INT UNSIGNED;
	DECLARE in_suspended TINYINT(1);
	DECLARE in_dateSuspended DATE;
	DECLARE in_salt CHAR(30);
	DECLARE in_vbulletinUserID INT UNSIGNED;
	DECLARE in_syncPass TINYINT(1);
	DECLARE in_messageFilter TINYINT(1);
	DECLARE in_currentKey TINYBLOB;
	DECLARE in_currentKeyTime TIMESTAMP;
	DECLARE in_flags SMALLINT UNSIGNED;
		DECLARE ACCTUID BIGINT(10);

	DECLARE cur1 CURSOR FOR SELECT UID, acct_uname, acct_passwd, acct_email, acct_accessLevel, acct_salt, acct_vbulletinUserID, acct_suspend, acct_suspendDate, acct_flags, acct_syncPass, acct_lastKey, acct_lastKeyTime, acct_lastCharUID FROM `accounts2`;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

	OPEN cur1;

	START TRANSACTION;

		read_loop: LOOP
			
			FETCH cur1 INTO ID, in_uname, in_passwd, in_email, in_accessLevel, in_salt, in_vbulletinUserID, in_suspended, in_dateSuspended, in_flags, in_syncPass, in_currentKey, in_currentKeyTime, in_lastCharUsedID;
			IF done THEN
				LEAVE read_loop;
			END IF;

		IF NOT EXISTS(SELECT NULL FROM `obj_account` WHERE `acct_uname`= in_uname) THEN
			INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'account', NULL);
			SET UID = LAST_INSERT_ID();
		
			INSERT HIGH_PRIORITY INTO `obj_account` (`UID`, `acct_uname`, `acct_passwd`, `acct_email`, `acct_accessLevel`, `acct_lastCharUID`, `acct_suspend`, `acct_suspendDate`, `acct_salt`, `acct_vbulletinUserID`, `acct_syncPass`,  `acct_flags`, `acct_lastKey`, `acct_lastKeyTime`) VALUES (UID, in_uname, in_passwd, in_email, in_accessLevel, NULL, in_suspended, in_dateSuspended, in_salt, in_vbulletinUserID, in_syncPass, in_flags, in_CurrentKey, in_currentKeyTime);
		END IF;
		END LOOP;

	COMMIT;	

	CLOSE cur1;

END MAIN ;;
DELIMITER ;
