CREATE PROCEDURE `util_CHECK_UPDATE`()
MAIN: BEGIN

		
		DECLARE UID BIGINT UNSIGNED;
		DECLARE in_type ENUM('mobbase');
		DECLARE done int DEFAULT '0';

		DECLARE cur1 CURSOR FOR SELECT `ID`, `type` FROM `dyn_update_required`;
		DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
	
		OPEN cur1;

		START TRANSACTION;

			read_loop: LOOP
			
				FETCH cur1 INTO UID, in_type;
				IF done THEN
					LEAVE read_loop;
				END IF;

				IF (in_type = 'mobbase') THEN
					SELECT 'mobbase' AS `type`, `ID`, `loadID`, `lootTableID`, `name`, `level`, `health`, `stamina`, `mana`, `atrMod`, `defMod`, `damageMod`, `goldMod`, `seeInvis`, `AI`, `runSpeed`, `resistID`, `flags`, `immune`, `noaggro`, `spawnTime` FROM `static_npc_mobbase` WHERE `static_npc_mobbase`.`ID` = UID;
				END IF;

			END LOOP;

			SET @dyn_sql = CONCAT('DELETE FROM `dyn_update_required`;');
			PREPARE stmt1 FROM @dyn_sql;
			EXECUTE stmt1;

		COMMIT;	

		CLOSE cur1;

	END MAIN ;;
DELIMITER ;
