								SELECT
									`obj_warehouse`.*, `object`.`parent`,
									`object`.`type`
								FROM
									`object`
								LEFT JOIN `obj_warehouse` ON `object`.`UID` = `obj_warehouse`.`UID`
								WHERE
									`object`.`UID` = warehouseUID ; COMMIT ;
								END MAIN ;;
