CREATE PROCEDURE `wipe_cities`()
BEGIN

delete from object where UID > 1087 and type = 'zone';

update obj_guild set ownedCity = 0 WHERE UID > 25;

update obj_realm set rulingCityUID = 0, ruledSince = NULL;

END ;;
