CREATE PROCEDURE `zone_CREATE`(IN `xoor` FLOAT, IN `zoor` FLOAT, IN `yoor` FLOAT, IN `loadNum` INT UNSIGNED, IN `n` VARCHAR(60), IN `safezone` TINYINT UNSIGNED, IN `i1` VARCHAR(60), IN `i2` VARCHAR(60), IN `i3` VARCHAR(60), IN `pcity` TINYINT UNSIGNED, IN `parent` BIGINT UNSIGNED)
    MODIFIES SQL DATA
MAIN: BEGIN

		
		DECLARE UID BIGINT UNSIGNED;
		DECLARE parentType VARCHAR(50);

		
		DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
		BEGIN 
			ROLLBACK; 
			SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
		END;
		
		

		IF ISNULL(parent) THEN
			SELECT -2 AS `errorno`, "Parent (object) UID CANNOT be null" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		SELECT `type` INTO parentType FROM `object` WHERE `object`.`UID` = parent;

		IF ISNULL(parentType) THEN
			SELECT -3 AS `errorno`, "Parent (object) UID MUST Exist" AS `errormsg`;
			LEAVE MAIN;
		ELSEIF parentType NOT IN ('worldserver', 'zone') THEN
			SELECT -4 AS `errorno`, "Parent (object) UID of a zone MUST BE a ZONE or WORLD" AS `errormsg`;
			LEAVE MAIN;
		END IF;

		

		START TRANSACTION;

		INSERT HIGH_PRIORITY INTO object VALUES (NULL, 'zone', parent);
		SET UID = LAST_INSERT_ID();

		INSERT HIGH_PRIORITY INTO `obj_zone` (`UID` ,`XCoord` ,`ZCoord` ,`YOffset` ,`LoadNum` ,`Name` ,`SafeZone` ,`Icon1` ,`Icon2` ,`Icon3` ,`isPlayerCity`) VALUES (UID, xoor, zoor, yoor, loadNum, n, safezone, i1, i2, i3, pcity);

		COMMIT;

		

		SELECT UID AS `result`;

	END MAIN ;;
DELIMITER ;
