CREATE PROCEDURE `zone_GETBYUID`(IN `n` BIGINT UNSIGNED)
    MODIFIES SQL DATA
MAIN: BEGIN

	DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING, NOT FOUND 
	BEGIN 
		ROLLBACK; 
		SELECT -1 AS `errorno`, "SQL Error: A rollback has occured." AS `errormsg`;
	END;
		
	SELECT * FROM `obj_zone` WHERE `obj_zone`.`UID` = n LIMIT 1;

END MAIN ;;
