	END;

	SET @dyn_sql = CONCAT('UPDATE `obj_zone` SET ',in_name,' = ? WHERE `obj_zone`.`UID` = ? LIMIT 1;'), @new_value = in_new_value, @uid = uid;
	PREPARE stmt1 FROM @dyn_sql;
